class Solution:
    def countNetworks(self, n: int, edges: List[List[int]]) -> int:
        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)
        seen = [False] * n
        count = 0
        for s in range(n):
            if seen[s]:
                continue
            count += 1
            seen[s] = True
            queue = deque([s])
            while queue:
                for v in adj[queue.popleft()]:
                    if not seen[v]:
                        seen[v] = True
                        queue.append(v)
        return count

