class UnionFind {
  parent: number[];
  rank: number[];
  constructor(n: number) {
    this.parent = Array.from({ length: n }, (_, i) => i);
    this.rank = new Array(n).fill(0);
  }
  find(x: number): number {
    let root = x;
    while (this.parent[root] !== root) root = this.parent[root];
    while (this.parent[x] !== root) { // path compression: point the whole path at the root
      const next = this.parent[x];
      this.parent[x] = root;
      x = next;
    }
    return root;
  }
  union(a: number, b: number): boolean {
    let ra = this.find(a), rb = this.find(b);
    if (ra === rb) return false; // already in the same set
    if (this.rank[ra] < this.rank[rb]) [ra, rb] = [rb, ra];
    this.parent[rb] = ra; // shorter tree goes under the taller one
    if (this.rank[ra] === this.rank[rb]) this.rank[ra]++;
    return true;
  }
}

function countNetworks(n: number, edges: number[][]): number {
  const uf = new UnionFind(n);
  let count = n;
  for (const [a, b] of edges) if (uf.union(a, b)) count--;
  return count;
}

